// ─── Open-axis registry (engine seeds OCEAN+H; modules add axes) ───
export interface TraitAxisDef { key: string; seed: number; min: number; max: number; }
export function registerTraitAxis(def: Partial<TraitAxisDef> & { key: string }): void;
export function getTraitAxes(): readonly TraitAxisDef[];   // OCEAN+H always present + module axes

// ─── PlasticityRule (pure module data; engine owns the law) ───
export interface PlasticityRule {
  id: string;                         // stable, used for accumulator key 'pp:<id>'
  axis: string;                       // trait axis key to deform (must be a registered axis)
  when: {
    eventType?: string;               // matched against processed events (INV-14: opaque to engine)
    abilityUse?: string;              // SPEC-2 seam: an affordance-modifier id whose USE triggers this
    predicate?: (ctx: PlasticityTriggerCtx) => boolean;  // module-supplied gate (self-action etc.)
  };
  mode: 'threshold' | 'accumulation';
  step: number;                       // signed axis-unit shift (threshold: per cross; accumulation: per trigger)
  threshold?: number;                 // required for mode==='threshold'
  // optional magnitude scaling from the two state seams (both default 1)
  magnitudeScale?: (ctx: PlasticityTriggerCtx) => number; // reads self-belief / sentiment-to-target
  // optional reversibility — written onto the axis ScalarAttribute.drift on first shift; absent = irreversible
  anneal?: { ratePerMinute: number; toward: number };
  // optional seam emissions (decoupled; null-safe)
  emitBelief?: (ctx: PlasticityTriggerCtx) => { eventType: string; object: string|null; source: string; confidence: number } | null;
}
export interface PlasticityTriggerCtx {
  agent: Agent;                       // the bearer (bilateral: may be player)
  targetId?: string;                  // for cross-agent / sentiment-scaled rules
  event?: WorldEvent;                 // the matched event, if event-driven
  selfBeliefConfidence: (matcher: (eventType: string) => boolean) => number; // wraps beliefs.getMaxConfidenceFor(self,...)
  sentimentTo: (id: string) => number; // wraps relationships.getRelationship(id)?.sentiment ?? 0
}
export function registerPlasticityRule(rule: PlasticityRule): void;
export function getPlasticityRules(): readonly PlasticityRule[];
export function clearPlasticityRules(): void;   // test-support (mirrors clearScoringContributors)

// ─── World API (thin; all writes route through the EXISTING permanent-base op) ───
class World {
  // effective trait read (state axis → profile seed → 0.5). Bilateral.
  getTrait(npcId: string, axis: string): number;
  // PLASTIC shift — wraps adjustAttributeBase('trait:'+axis); writes anneal.drift on first shift; clamps finite.
  // Emits onTraitChange (new callback, parallels onMoodChange) when |Δ|>0.0005.
  applyPlasticShift(npcId: string, axis: string, delta: number, anneal?: {ratePerMinute:number; toward:number}): number;
  // ELASTIC trait modifier (rare; e.g. a temporary disposition buff). Wraps addAttributeModifier('trait:'+axis,...).
  addTraitModifier(npcId: string, axis: string, mod: Omit<AttributeModifier,'id'>): void;
}

// ─── Agent accessor (the SINGLE read seam all ~17 sites switch to) ───
class Agent {
  // attributeEffective(state.attributes['trait:'+axis]) ?? profile.bigFive[map] ?? 0.5
  trait(axis: string): number;
}

synthesis.spec:
SPEC 2 — AFFORDANCE-SPACE MODIFIER (engine layer, genre-neutral). Status: implementation-ready. Engine never contains the words Negation/trauma/wound/debt.

## 0. THE LAW (one sentence)
An agent's or a zone's STATE can override the SET OF POSSIBLE ACTIONS for a TARGET (itself, another agent, or every agent in a zone), as pure registered data; the engine evaluates these overrides through the SAME requirement-checker path that already gates every NPC and player action.

This is NOT a new pipeline. It is a third REQUIREMENT_CHECKER family (`affordanceOverride`) plus a tiny carrier for the override records and a zone-state store. Possibility-toggling rides the EXISTING binary requirement gate (al.ts:304 checkRequirements + al.ts:510 validatePlayerAction); strength-scaling rides the EXISTING continuous scoring channel (registerScoringContributor, al.ts:439). Conflating the two is the central design error we explicitly avoid (DEC-1).

## 1. DATA MODEL

### 1.1 The override record — AffordanceOverride (engine/src/affordance-modifier.ts, NEW)
```ts
export type OverrideMode = 'forbid' | 'permit';   // forbid = remove from possible set; permit = restore an otherwise-gated action
export interface AffordanceOverride {
  id: string;                       // uuid, dedup/removal key
  source: string;                   // human-readable origin, e.g. 'power_use', 'curfew' (module string, NEVER engine vocab)
  category: string;                 // stacking/removal group (module-defined)
  /** WHO is projecting this. 'agent' (sourceId is an agent id) | 'zone' (sourceId is a location id). */
  sourceKind: 'agent' | 'zone';
  sourceId: string;
  /** Open predicate over the affordance being gated. ALL present clauses must match (AND). Empty = matches every action. */
  match: {
    affordanceIds?: string[];       // exact affordance id allow/deny list
    categories?: string[];          // match aff.category
    minSeverity?: number;           // match aff.severity >= n  (genre-neutral: severity already exists)
    tags?: string[];                // match aff.tags (NEW open field on AffordanceDefinition, see 1.4)
  };
  mode: OverrideMode;
  /** Lifecycle (mirrors AttributeModifier/MoodModifier exactly). */
  remaining: number;                // game minutes left; 0 = permanent until removed
  duration: number;                 // original duration for parity with modifier model (informational)
  /** Optional strength in [0,1]. Drives SCORING only (not possibility). Undefined = no scoring effect (pure gate). */
  strength?: number;
  /** Optional dynamic strength scaling — engine resolves at read time from bearer state (see 1.3). */
  strengthScale?: AffordanceStrengthScale;
  /** SEAM to SPEC 1: USING this override (i.e. the source actor performing the gated action that this
   *  override made possible, OR the act of projecting it) is a plasticity trigger. Carries the trigger spec
   *  the plasticity layer consumes. Engine treats it as opaque data and forwards it (INV-14). */
  plasticityTrigger?: unknown;      // PlasticityTriggerSpec from SPEC 1; engine never reads its fields
}
```
`mode:'permit'` is symmetric with `forbid` and is what makes this a true affordance-SPACE override (not just a stricter gate): a zone or an actor can ENABLE an action that the base requirement set forbids. Without permit, "affordance-space modifier" degenerates into "extra blocker" — permit is load-bearing for the Type II / module-realizability target.

### 1.2 Carriers (where overrides live)
TWO carriers, both new, both genre-neutral, both following the existing optional-field + INV-21 default-on-load discipline:

(a) AGENT-borne overrides — `AgentState.affordanceOverrides?: AffordanceOverride[]` (engine/src/agent-types.ts, alongside attributes/factions). Holds overrides this agent is SOURCING (self-override has sourceKind:'agent', sourceId===self; cross-agent override has sourceId===self, target resolved at match time — see 1.5). Optional → old saves lack it (INV-21).

(b) ZONE-borne overrides — NEW `ZoneState` store, because LocationDef (world-types.ts:24) is STATIC config with no mutable state and there is no stateful "object of reality" today. Add to World a parallel mutable map:
```ts
// world.ts
private zoneStates: Map<string, ZoneState> = new Map();   // keyed by location id
// agent-types.ts (or a new zone-types.ts)
export interface ZoneState {
  /** Open scalar attributes for the zone — SAME ScalarAttribute primitive as agents (reuse, no new math). */
  attributes?: Record<string, ScalarAttribute>;
  /** Affordance overrides this zone projects onto agents within it. */
  affordanceOverrides?: AffordanceOverride[];
}
```
This makes a zone a first-class "active object of reality" with state, reusing the EXACT ScalarAttribute deformation machinery agents use — the zone can have plastic attributes too, and its override strength can scale from them. ZoneState is created lazily (getOrCreateZoneState) so locations without overrides cost nothing.

### 1.3 Strength scaling — AffordanceStrengthScale (genre-neutral, no possibility effect)
```ts
export interface AffordanceStrengthScale {
  /** Multiply strength by the bearer's max self-belief confidence for beliefs matching this eventType.
   *  Engine calls beliefs.getMaxConfidenceFor(selfId, b => b.eventType===eventType) — module supplies the
   *  eventType, engine never enumerates which event types are "self-relevant" (INV-14). */
  fromSelfBelief?: { eventType: string; weight: number };
  /** Multiply strength by sentiment toward the TARGET (cross-agent only). Uses RAW rel.sentiment
   *  (-1..1), NOT the crime-tuned sentimentCurve — sentimentCurve imports crime thresholds, raw is neutral. */
  fromSentimentToTarget?: { weight: number; abs?: boolean };
  /** Multiply strength by a zone/agent attribute's effective value (open key). */
  fromAttribute?: { key: string; weight: number };
}
```
Resolution (engine helper `resolveOverrideStrength(ov, sourceAgentOrZone, targetId, ctx)`): start at `ov.strength ?? 1`, multiply by each present scale clause. Null relationship → contributes 0 (matches al.ts:461 semantics); strangers with no relationship row yield 0 strength via that channel (DEC-7 default, parallels getTestimonyWeight's 0.3 fallback documented but NOT auto-applied — modules opt in). Belief confidence is floored at 0.1 (beliefs.ts:115), never 0 — so "no self-belief ⇒ zero strength" is false; a baseline floor is inherent and documented (risk noted).

### 1.4 AffordanceDefinition.tags (NEW open field)
Add `tags?: string[]` to AffordanceDefinition (al.ts:93). Purely for override matching (and future module use). Open string set, engine assigns no meaning. Lets a module forbid "all violent actions" without enumerating ids. Backward-compat: optional, absent = no tags.

### 1.5 Cross-agent resolution model (the subtle part)
An override with sourceKind:'agent' and a target dimension needs to gate the TARGET's possible set, but it is STORED on the source. Resolution at gate time (DEC-3): the engine, when checking whether agent T can do affordance A, scans for applicable overrides projected ONTO T from:
  - T's own AgentState.affordanceOverrides where sourceId===T (self-overrides), AND
  - the ZoneState.affordanceOverrides of T's current location (zone overrides), AND
  - any OTHER agent S co-present with T whose AgentState.affordanceOverrides contains a record explicitly targeting T (cross-agent). Cross-agent records carry a `targetId` inside match (added to match: `targetId?: string` — when set, override only applies when the gated agent === targetId). Co-presence is required (perception.getCoPresent) so projection is spatially grounded and cheap.
This keeps storage on the source (so removal/lifecycle is owned by the projector) while evaluation is target-centric.

## 2. AL INTEGRATION — bilateral, single path

### 2.1 The gate: a built-in requirement family, not a per-module checker
Possibility-toggling MUST be reachable from BOTH checkRequirements (NPC, al.ts:304) AND validatePlayerAction (player, al.ts:510), or bilateral parity breaks (INV-16/17). The code map flags that validatePlayerAction re-implements requirement iteration and does NOT call checkPostTargetRequirements. Therefore the override gate is a UNIVERSAL pre-target gate evaluated by a single shared engine function, called by both paths — NOT a POST_TARGET checker (which the player path skips), NOT a per-module REQUIREMENT_CHECKER entry (modules don't register it; the engine owns the law, modules supply the data on the carriers).

New shared function (engine, genre-neutral):
```ts
// affordance-modifier.ts
export function isAffordanceForbidden(aff: AffordanceDefinition, agent: Agent, ctx: AffordanceContext): boolean {
  // Collect applicable overrides onto `agent` from self + zone + co-present projectors (1.5).
  // Apply forbid/permit with precedence (DEC-4): explicit permit beats forbid only if its source is
  // more specific OR strength-ordered? -> resolved in DEC-4 below.
  // Returns true if the action is removed from the possible set for THIS agent right now.
}
```
Wiring:
  - checkRequirements (al.ts:304): add `if (isAffordanceForbidden(aff, agent, ctx)) return null;` immediately after the universal pre-target gates (after suppressNearPlayer line 315, before checkRegistryRequirements 318).
  - checkRequirementsReactive (al.ts:333): add the SAME line after line 344. The reactive path skips mood but the override gate is NOT mood — a forbid must hold under all conditions (risk: reactive deliberately relaxes; override is a hard possibility gate, so it runs in both, by design DEC-6).
  - validatePlayerAction (al.ts:510): add the SAME `isAffordanceForbidden(aff, playerAgent, ctx)` check after the period gate (line 526), before the REQUIREMENT_CHECKERS loop. Player is now gated identically — player has full bilateral parity as TARGET of overrides (zone curfew applies to player; an NPC's cross-agent forbid applies to player).

Because the gate is one shared pure function consulted by all three entry points, there is ZERO possibility of split-brain (the failure mode the code map warns about with post-target checkers).

### 2.2 The scoring channel: strength via the existing contributor
Strength scaling rides registerScoringContributor (al.ts:439), NOT the gate. A module that wants "an override I project makes the gated action MORE attractive to me / my ally" registers a ScoringContributor that reads the agent's applicable `permit` overrides and adds `weight * resolveOverrideStrength(...)`. The engine ships ONE built-in optional contributor `affordanceOverrideScoringContributor` (registered by the server at boot, not auto-global, to respect the SCORING_CONTRIBUTORS test-isolation rule al.ts:445) that adds `permit`-override strength to computeUtility for actions the override enables. This cleanly separates: gate decides POSSIBLE; scoring decides ATTRACTIVE (DEC-1). No "scored but impossible" (a forbidden action is never scored because checkRequirements returns null before scoring) and no "possible but never chosen" beyond normal utility dynamics.

### 2.3 Target finders untouched
findTarget/findReactiveTarget (al.ts:359/374) are NOT modified. Cross-agent overrides are evaluated target-centrically in isAffordanceForbidden when the TARGET agent's own possible set is computed — A altering T's set means T's checkRequirements sees the forbid. No change to "who can A target".

## 3. LIFECYCLE + TICK
Reuse the existing tick at world.ts:561 (bilateral — iterates all agents incl. player). Add to _tickMoodSystem's per-agent body (next to attribute decay at world.ts:592) a decay of agent overrides: `decayOverrides(agent.state.affordanceOverrides, 5)` (same dt=5, same remaining-- / splice-on-expiry as decayAttribute). Add a SEPARATE small loop after the agent loop to decay each ZoneState's overrides (zones are not agents and are not in the agent loop). Zone attributes (if any) decay+drift via the same decayAttribute/driftAttribute reused on ZoneState.attributes.
  - Permanent overrides (remaining=0) never expire — removed only via World.removeAffordanceOverride(category) (mirrors removeModifiers, world.ts:651).
  - No new tick phase needed; module lifecycle (e.g. "override lasts until X") rides registerTickPhaseHandler as today.

## 4. SEAM TO SPEC 1 (plasticity)
USING an affordance override is a plasticity trigger ("a piece of yourself"). Mechanism, fully decoupled (engine forwards opaque data):
  - When an agent SUCCESSFULLY performs an action that an override of theirs made possible (mode:'permit', sourceId===actor) OR projects a cross-agent/zone override, the engine emits a neutral hook the plasticity layer subscribes to. Concretely: World exposes `onAffordanceOverrideUsed?(actorId, ov)` callback (parallels onMoodChange). The override's `plasticityTrigger` opaque blob is passed through. SPEC 1's plasticity layer registers as the consumer and applies a base-shift to a trait axis (adjustAttributeBase-style permanent set) scaled by the trigger spec — engine never knows it's a "cost". This is the Type I realization (self affordance-override + plasticity cost) as pure module data.
  - The seam is one-directional and optional: an override with no plasticityTrigger costs nothing (a free power); one with a trigger pays via SPEC 1. The "no one does both" Negation rule is a module constraint expressed by which overrides carry triggers vs which scale from belief — engine is agnostic.

## 5. WORLD API (genre-neutral, mirrors attribute API)
```ts
// Agent-sourced
addAffordanceOverride(npcId: string, ov: Omit<AffordanceOverride,'id'>): string   // returns id
removeAffordanceOverride(npcId: string, category: string): void
getAffordanceOverrides(npcId: string): readonly AffordanceOverride[]
// Zone-sourced (NEW)
addZoneAffordanceOverride(locationId: string, ov: Omit<AffordanceOverride,'id'>): string
removeZoneAffordanceOverride(locationId: string, category: string): void
getZoneState(locationId: string): ZoneState | undefined
setZoneAttribute / adjustZoneAttributeBase / addZoneAttributeModifier  // reuse ScalarAttribute, mirror agent API
```
All finite-guarded (reject NaN strength/remaining like addModifier, world.ts:615). No transferAttribute analog for overrides (overrides aren't conserved — DEC-8).

## 6. SAVE/LOAD (INV-21)
Extend WorldSaveAgentData (world.ts:89) with `affordanceOverrides?: AffordanceOverride[]`, written with the omit-when-empty pattern in toJSON (world.ts:1892: `...(agent.state.affordanceOverrides ? {affordanceOverrides:...} : {})`). On load (world.ts:1974 block) restore with SL-07 finite-filtering (drop any with non-finite remaining/strength) and INV-21 default (absent ⇒ field stays undefined, no overrides — safe). Add a NEW top-level `zoneStates?: Record<string, ZoneState>` to WorldSaveData + toJSON/loadState (serialize the zoneStates map → record; restore with same finite-filtering on each zone's attributes and overrides). Old saves lack both → load to empty, zero behavior change.

## 7. PHASING
- Phase 1 (gate + agent self-override): AffordanceOverride type, AgentState.affordanceOverrides, isAffordanceForbidden, wire into checkRequirements + checkRequirementsReactive + validatePlayerAction, World add/remove/get for agent, decay in tick, save/load for agent overrides. tags field on AffordanceDefinition. TESTS: forbid removes from possible set (NPC + player parity), permit restores, expiry. This alone realizes self affordance-override.
- Phase 2 (strength scaling + scoring): AffordanceStrengthScale, resolveOverrideStrength, the built-in scoring contributor (server-registered), fromSelfBelief/fromSentimentToTarget/fromAttribute. TESTS: scored-but-possible, strangers→0, belief floor.
- Phase 3 (zone carrier): ZoneState, zoneStates map, World zone API, zone-override gating in isAffordanceForbidden (zone of target's location), zone decay loop, zone save/load. TESTS: curfew-style zone forbid applies to all co-present incl player; zone attribute drift.
- Phase 4 (cross-agent + plasticity seam): match.targetId, co-present projector scan, onAffordanceOverrideUsed callback + plasticityTrigger passthrough. TESTS: A forbids T's action when co-present, not when apart; using a permit override fires the plasticity callback with the opaque trigger; player as cross-agent target.

Each phase is independently shippable, tsc-0, bun-test-green; crime/economy oracle behavior unchanged because no override data exists until a module adds it.

