// engine/src/affordance-modifier.ts (NEW) — genre-neutral, zero module strings (INV-14)
export type OverrideMode = 'forbid' | 'permit';
export interface AffordanceMatch { affordanceIds?: string[]; categories?: string[]; minSeverity?: number; tags?: string[]; targetId?: string; }
export interface AffordanceStrengthScale { fromSelfBelief?: { eventType: string; weight: number }; fromSentimentToTarget?: { weight: number; abs?: boolean }; fromAttribute?: { key: string; weight: number }; }
export interface AffordanceOverride { id: string; source: string; category: string; sourceKind: 'agent' | 'zone'; sourceId: string; match: AffordanceMatch; mode: OverrideMode; remaining: number; duration: number; strength?: number; strengthScale?: AffordanceStrengthScale; plasticityTrigger?: unknown; }
export interface ZoneState { attributes?: Record<string, import('./attributes').ScalarAttribute>; affordanceOverrides?: AffordanceOverride[]; }

// matching (AND over present clauses; empty match = matches everything)
export function overrideMatches(ov: AffordanceOverride, aff: AffordanceDefinition, gatedAgentId: string): boolean;
// strength resolution (SCORING only, never gate)
export function resolveOverrideStrength(ov: AffordanceOverride, source: { beliefs?; relationships?; attributes? }, targetId: string | undefined, /* getMaxConfidenceFor/getRelationship/getAttributeValue */): number;
// THE GATE — collects applicable overrides onto `agent` (self + zone-of-agent-location + co-present projectors w/ match.targetId===agent), applies forbid/permit w/ DEC-4 precedence, returns true if removed from possible set
export function isAffordanceForbidden(aff: AffordanceDefinition, agent: Agent, ctx: AffordanceContext): boolean;
// lifecycle (mirrors decayAttribute splice idiom, dt-driven)
export function decayOverrides(list: AffordanceOverride[] | undefined, dtMinutes: number): void;

// World API additions (world.ts) — finite-guarded (world.ts:615 idiom)
addAffordanceOverride(npcId: string, ov: Omit<AffordanceOverride,'id'|'sourceKind'|'sourceId'>): string;   // sourceKind='agent', sourceId=npcId set by engine
removeAffordanceOverride(npcId: string, category: string): void;
getAffordanceOverrides(npcId: string): readonly AffordanceOverride[];
getOrCreateZoneState(locationId: string): ZoneState;   // lazy
getZoneState(locationId: string): ZoneState | undefined;
addZoneAffordanceOverride(locationId: string, ov: Omit<AffordanceOverride,'id'|'sourceKind'|'sourceId'>): string;
removeZoneAffordanceOverride(locationId: string, category: string): void;
setZoneAttribute(locationId,key,base,min,max): void;  adjustZoneAttributeBase(locationId,key,delta): number;  addZoneAttributeModifier(locationId,key,mod): void;   // all reuse attributes.ts

// AffordanceContext (al.ts:152) gains read access to zone overrides via ctx.locations is config-only,
// so isAffordanceForbidden needs zone state: pass it through ctx as ctx.getZoneOverrides?(locId) (engine-supplied closure) OR thread World — chosen: ctx.zoneOverridesFor?: (locId) => readonly AffordanceOverride[] (optional, engine sets it; modules never see it).

// Callback (parallels onMoodChange)
onAffordanceOverrideUsed?: (actorId: string, override: AffordanceOverride) => void;

// AffordanceDefinition (al.ts:93) gains: tags?: string[];

// Save shapes
WorldSaveAgentData += affordanceOverrides?: AffordanceOverride[];
WorldSaveData += zoneStates?: Record<string, ZoneState>;
